@Override
public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
  L.beginSection(drawTraceName);
  if (!visible || layerModel.isHidden()) {
    L.endSection(drawTraceName);
    return;
  }
  buildParentLayerListIfNeeded();
  computeParentMatrix(parentMatrix);

  int alpha = computeLayerAlpha(parentAlpha);

  // Fast path: without a matte, masks, or a non-normal blend mode there is no need for an
  // intermediate offscreen buffer, so draw straight to the canvas.
  if (!hasMatteOnThisLayer() && !hasMasksOnThisLayer() && getBlendMode() == LBlendMode.NORMAL) {
    matrix.preConcat(transform.getMatrix());
    drawLayerTraced(canvas, alpha, shadowToApply);
    recordRenderTime(L.endSection(drawTraceName));
    return;
  }

  computeDrawBounds(canvas, parentMatrix);

  // Ensure that what we are drawing is >=1px of width and height.
  // On older devices, drawing to an offscreen buffer of <1px would draw back as a black bar.
  // https://github.com/airbnb/lottie-android/issues/1625
  if (rect.width() >= 1f && rect.height() >= 1f) {
    drawLayerWithMasksAndMatte(canvas, parentMatrix, parentAlpha, alpha, shadowToApply);
  }

  drawDebugOutlineIfNeeded(canvas);

  recordRenderTime(L.endSection(drawTraceName));
}

/**
 * Builds the composite matrix for this layer by concatenating every parent layer's matrix onto
 * {@code parentMatrix}. The result is stored in {@link #matrix}.
 */
private void computeParentMatrix(Matrix parentMatrix) {
  if (L.isTraceEnabled()) {
    L.beginSection("Layer#parentMatrix");
  }
  matrix.reset();
  matrix.set(parentMatrix);
  for (int i = parentLayers.size() - 1; i >= 0; i--) {
    matrix.preConcat(parentLayers.get(i).transform.getMatrix());
  }
  if (L.isTraceEnabled()) {
    L.endSection("Layer#parentMatrix");
  }
}

private int computeLayerAlpha(int parentAlpha) {
  // It is unclear why but getting the opacity here would sometimes NPE.
  // The extra code here is designed to avoid this.
  // https://github.com/airbnb/lottie-android/issues/2083
  int opacity = 100;
  BaseKeyframeAnimation<?, Integer> opacityAnimation = transform.getOpacity();
  if (opacityAnimation != null) {
    Integer opacityValue = opacityAnimation.getValue();
    if (opacityValue != null) {
      opacity = opacityValue;
    }
  }
  return (int) ((parentAlpha / 255f * (float) opacity / 100f) * 255);
